python3 - <<'EOF'
import defusedxml.ElementTree as ET
import sys

BPMN_NS = 'http://www.omg.org/spec/BPMN/20100524/MODEL'
UIPATH_NS = 'http://uipath.org/schema/bpmn'

def q(ns, tag): return f'{{{ns}}}{tag}'

path = '/work/output/artifacts/skill-bpmn-e2e-invoice-exception-triage/InvoiceExceptionTriage/InvoiceExceptionTriage.bpmn'
tree = ET.parse(path)
root = tree.getroot()
errors = []

# 1. Root namespace
if 'http://www.omg.org/spec/BPMN/20100524/MODEL' not in root.tag and 'definitions' not in root.tag.lower():
    errors.append('Root is not bpmn:definitions')

# Collect all IDs
all_ids = {el.get('id') for el in root.iter() if el.get('id')}

# 2. Diagram
diagrams = root.findall(f'{{http://www.omg.org/spec/BPMN/20100524/DI}}BPMNDiagram')
if len(diagrams) != 1:
    errors.append(f'Expected 1 BPMNDiagram, found {len(diagrams)}')

shapes = root.findall('.//{http://www.omg.org/spec/BPMN/20100524/DI}BPMNShape')
edges  = root.findall('.//{http://www.omg.org/spec/BPMN/20100524/DI}BPMNEdge')
shape_refs = {s.get('bpmnElement') for s in shapes}
edge_refs  = {e.get('bpmnElement') for e in edges}

proc = root.find(q(BPMN_NS, 'process'))
flow_nodes = [el for el in proc if el.get('id') and el.tag != q(BPMN_NS,'sequenceFlow')]
seq_flows  = proc.findall(q(BPMN_NS, 'sequenceFlow'))

for fn in flow_nodes:
    fid = fn.get('id')
    if fid not in shape_refs:
        errors.append(f'No BPMNShape for {fid}')
for sf in seq_flows:
    sfid = sf.get('id')
    if sfid not in edge_refs:
        errors.append(f'No BPMNEdge for {sfid}')

# 3. All refs resolve
for sf in seq_flows:
    for attr in ('sourceRef', 'targetRef'):
        ref = sf.get(attr)
        if ref and ref not in all_ids:
            errors.append(f'sequenceFlow {sf.get("id")} {attr}={ref} not found')

# 4. XOR gateway conditions
for gw in proc.findall(q(BPMN_NS, 'exclusiveGateway')):
    default = gw.get('default')
    non_default_without_cond = []
    for out_id_elem in gw.findall(q(BPMN_NS, 'outgoing')):
        out_id = out_id_elem.text.strip()
        if out_id == default:
            continue
        sf = next((s for s in seq_flows if s.get('id') == out_id), None)
        if sf is not None and sf.find(q(BPMN_NS, 'conditionExpression')) is None:
            non_default_without_cond.append(out_id)
    if non_default_without_cond:
        errors.append(f'Gateway {gw.get("id")}: non-default flows missing condition: {non_default_without_cond}')
    if not default:
        errors.append(f'Gateway {gw.get("id")} has no default flow')

# 5. No activity/event with >1 incoming
for el in proc:
    inc = el.findall(q(BPMN_NS, 'incoming'))
    if len(inc) > 1:
        errors.append(f'{el.get("id")} has {len(inc)} incoming flows (max 1 without join gateway)')

# 7. vars references
vars_ids = {v.get('id') for v in root.findall(f'.//{{{UIPATH_NS}}}inputOutput') + root.findall(f'.//{{{UIPATH_NS}}}input[@type]') }
# Just check declared vars exist for var= references
for out_el in root.findall(f'.//{{{UIPATH_NS}}}output'):
    var_ref = out_el.get('var')
    if var_ref:
        declared = {v.get('id') for v in root.findall(f'.//{{{UIPATH_NS}}}inputOutput')}
        if var_ref not in declared:
            errors.append(f'output var="{var_ref}" not declared in variables')

if errors:
    print('ERRORS:')
    for e in errors: print(' ', e)
    sys.exit(1)
else:
    print('VALID - all structural checks passed')
    print(f'  {len(flow_nodes)} flow nodes, {len(seq_flows)} flows, {len(shapes)} shapes, {len(edges)} edges')
EOF

